1	package com.example.starter.blind;
2	
3	import org.junit.jupiter.api.Test;
4	import org.springframework.beans.factory.annotation.Autowired;
5	import org.springframework.boot.test.context.SpringBootTest;
6	import org.springframework.boot.test.web.client.TestRestTemplate;
7	import org.springframework.http.HttpEntity;
8	import org.springframework.http.HttpHeaders;
9	import org.springframework.http.HttpMethod;
10	import org.springframework.http.MediaType;
11	import org.springframework.http.ResponseEntity;
12	
13	import java.util.ArrayList;
14	import java.util.HashSet;
15	import java.util.List;
16	import java.util.Set;
17	import java.util.concurrent.ExecutorService;
18	import java.util.concurrent.Executors;
19	import java.util.concurrent.Future;
20	import java.util.concurrent.TimeUnit;
21	
22	import static org.junit.jupiter.api.Assertions.assertEquals;
23	import static org.junit.jupiter.api.Assertions.assertTrue;
24	
25	/**
26	 * 并发与幂等边界（真实多线程，不用睡眠代替断言）：
27	 * 并发分配不重席位；同 requestId 并发恰好一次业务执行且全部得到成功回放；
28	 * 同键异参并发只有一次成功，其余 409。
29	 */
30	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
31	class ConcurrencyTest extends AbstractBlindIntegrationTest {
32	
33	    @Autowired
34	    private TestRestTemplate rest;
35	
36	    private HttpHeaders headers(String actor, String role, String requestId) {
37	        HttpHeaders h = new HttpHeaders();
38	        h.set("X-Actor-Id", actor);
39	        h.set("X-Role", role);
40	        if (requestId != null) {
41	            h.set("X-Request-Id", requestId);
42	        }
43	        h.setContentType(MediaType.APPLICATION_JSON);
44	        return h;
45	    }
46	
47	    @Test
48	    void concurrentRegistrations_distinctParticipants_noDoubleSeatAndExactlyCapacitySucceed()
49	            throws Exception {
50	        // 2 区组 = 8 席；12 个不同参与者并发：恰好 8 个 201、4 个 422
51	        assertEquals(201, rest.exchange("/api/experiments/CONC-1", HttpMethod.POST,
52	                new HttpEntity<>("{\"blockCount\":2}",
53	                        headers("c1", "COORDINATOR", "conc-create")), String.class)
54	                .getStatusCode().value());
55	
56	        int threads = 12;
57	        ExecutorService pool = Executors.newFixedThreadPool(8);
58	        List<Future<Integer>> futures = new ArrayList<>();
59	        try {
60	            for (int i = 1; i <= threads; i++) {
61	                final String pid = "CP" + i;
62	                final String reqId = "conc-alloc-" + i;
63	                futures.add(pool.submit(() -> rest.exchange(
64	                        "/api/experiments/CONC-1/participants/" + pid + "/allocations",
65	                        HttpMethod.POST, new HttpEntity<>(null,
66	                                headers("c1", "COORDINATOR", reqId)), String.class)
67	                        .getStatusCode().value()));
68	            }
69	            List<Integer> statuses = new ArrayList<>();
70	            for (Future<Integer> future : futures) {
71	                statuses.add(future.get(30, TimeUnit.SECONDS));
72	            }
73	            long success = statuses.stream().filter(s -> s == 201).count();
74	            long full = statuses.stream().filter(s -> s == 422).count();
75	            assertEquals(8, success, "恰好容量个分配成功");
76	            assertEquals(4, full, "其余因满额 422");
77	        } finally {
78	            pool.shutdown();
79	            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
80	        }
81	
82	        // 最终数据：8 条分配，席位两两不同，覆盖两个区组各 4 席
83	        assertEquals(8, jdbc.queryForObject(
84	                "SELECT COUNT(*) FROM allocation WHERE experiment_id = 'CONC-1'", Integer.class));
85	        List<String> seats = jdbc.queryForList(
86	                "SELECT CONCAT(block_no, '-', seat_no) AS k FROM allocation "
87	                        + "WHERE experiment_id = 'CONC-1'", String.class);
88	        assertEquals(8, new HashSet<>(seats).size(), "席位不得重复");
89	        assertEquals(Set.of("1-1", "1-2", "1-3", "1-4", "2-1", "2-2", "2-3", "2-4"),
90	                new HashSet<>(seats));
91	        List<String> participantDuplicates = jdbc.queryForList(
92	                "SELECT participant_id FROM allocation WHERE experiment_id = 'CONC-1' "
93	                        + "GROUP BY participant_id HAVING COUNT(*) > 1", String.class);
94	        assertTrue(participantDuplicates.isEmpty(), "同参与者不得占多席");
95	    }
