262	        ResponseEntity<String> approveReplay = exchange(
263	                "/api/unblind-requests/" + ubId + "/approval", HttpMethod.POST,
264	                headers("rev-2", "REVIEWER", "u4-approve-key"), null);
265	        assertEquals(200, approveReplay.getStatusCode().value());
266	        assertEquals(approve1.getBody(), approveReplay.getBody());
267	        assertEquals(1, jdbc.queryForObject(
268	                "SELECT COUNT(*) FROM unblind_request WHERE id = ? AND status = 'APPROVED' "
269	                        + "AND reviewer_actor = 'rev-2'", Integer.class, ubId));
270	    }
