            long id,
            String experimentId,
            String siteId,
            String blockCode,
            String participantId,
            int serialNo,
            String allocatorActor,
            long allocatedAt) {
    }

    private static final RowMapper<SiteAllocationRow> MAPPER = (rs, n) -> new SiteAllocationRow(
